function check(input, actual, expected) {
  const [water, starts] = input;
  if (!actual || typeof actual.output !== 'string' || !Array.isArray(actual.times)) return false;
  const { output, times } = actual;
  if (output.length !== water.length || times.length !== water.length) return false;
  // Arrival times of each kind, earliest first: molecule g is complete once hydrogen 2g+1 and oxygen g are in.
  const arrivals = { H: [], O: [] };
  for (let i = 0; i < water.length; i++) arrivals[water[i]].push(starts[i]);
  arrivals.H.sort((a, b) => a - b);
  arrivals.O.sort((a, b) => a - b);
  for (let g = 0; 3 * g < water.length; g++) {
    const group = output.slice(3 * g, 3 * g + 3);
    if (group.split('H').length - 1 !== 2 || group.split('O').length - 1 !== 1) return false;
    const ready = Math.max(arrivals.H[2 * g + 1], arrivals.O[g]);
    for (let k = 3 * g; k < 3 * g + 3; k++) if (times[k] !== ready) return false;
  }
  return true;
}

