function validate(input) {
  const [water, starts] = input;
  if (!/^[HO]+$/.test(water)) return 'water may contain only H and O.';
  if (water.length % 3 !== 0 || water.length > 60) return 'water.length must be 3 * n with 1 <= n <= 20.';
  if (water.split('O').length - 1 !== water.length / 3) return 'water needs exactly twice as many H as O.';
  if (starts.length !== water.length) return 'starts needs one start time per thread.';
  if (!starts.every((t) => Number.isInteger(t) && t >= 0 && t <= 1000)) return 'Each start time is an integer from 0 to 1000 ms.';
  return null;
}

