function adapt(input, solve, kit) {
  const [water, starts] = input, start = Date.now(), crossings = [];
  const h2o = new solve();
  for (const name of ['hydrogen', 'oxygen']) if (!h2o || typeof h2o[name] !== 'function') throw new Error(`H2O needs a method ${name}.`);
  let failure = null;
  [...water].forEach((atom, i) => {
    const method = atom === 'H' ? 'hydrogen' : 'oxygen';
    let crossed = false;
    const release = () => {
      if (crossed) failure = failure ?? `Thread ${i + 1} (${atom}) crossed the barrier twice.`;
      crossed = true;
      crossings.push({ atom, t: Date.now() - start });
      kit.trace(`Thread ${i + 1} (${atom}) crosses the barrier`);
    };
    setTimeout(() => {
      kit.trace(`Thread ${i + 1} (${atom}) arrives and calls ${method}()`);
      const result = h2o[method](release);
      if (result && typeof result.then === 'function') result.then(null, (error) => { failure = failure ?? `${method}() failed: ${error && error.message || error}`; });
    }, starts[i]);
  });
  // A correct solution has released every thread by the last arrival; the extra time shows late crossings.
  return new Promise((resolve, reject) => setTimeout(() => {
    if (failure) reject(new Error(failure));
    else resolve({ output: crossings.map((c) => c.atom).join(''), times: crossings.map((c) => c.t) });
  }, Math.max(...starts) + 50));
}

