class H2O {
  constructor() {
    this.hydrogens = [];
    this.oxygens = [];
  }

  async hydrogen(releaseHydrogen) {
    const pass = new Promise((resolve) => this.hydrogens.push(resolve));
    this.formMolecule();
    await pass;
    releaseHydrogen();
  }

  async oxygen(releaseOxygen) {
    const pass = new Promise((resolve) => this.oxygens.push(resolve));
    this.formMolecule();
    await pass;
    releaseOxygen();
  }

  formMolecule() {
    if (this.hydrogens.length < 2 || this.oxygens.length < 1) return;
    this.hydrogens.shift()();
    this.hydrogens.shift()();
    this.oxygens.shift()();
  }
}

