class H2O {
  constructor() {
    this.waiting = [];
  }

  // The arriving thread joins the waiting room; once two H and one O wait, release the earliest of them.
  arrive(atom, release) {
    this.waiting.push({ atom, release });
    const hydrogens = this.waiting.filter((w) => w.atom === 'H');
    const oxygens = this.waiting.filter((w) => w.atom === 'O');
    if (hydrogens.length < 2 || oxygens.length < 1) return;
    const molecule = [hydrogens[0], hydrogens[1], oxygens[0]];
    this.waiting = this.waiting.filter((w) => !molecule.includes(w));
    for (const w of molecule) w.release();
  }

  hydrogen(releaseHydrogen) { this.arrive('H', releaseHydrogen); }
  oxygen(releaseOxygen) { this.arrive('O', releaseOxygen); }
}

