function generate(rand, size) {
  const n = size === 'small' ? 1 + Math.floor(rand() * 4) : 15 + Math.floor(rand() * 6);
  const atoms = [...'H'.repeat(2 * n), ...'O'.repeat(n)];
  for (let i = atoms.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [atoms[i], atoms[j]] = [atoms[j], atoms[i]];
  }
  const top = size === 'small' ? 30 : 1000, roll = rand();
  const step = 1 + Math.floor(rand() * Math.floor(top / atoms.length));
  const starts = atoms.map((_, i) => (roll < 0.25 ? 0 : roll < 0.45 ? i * step : Math.floor(rand() * (top + 1))));
  return [atoms.join(''), starts];
}
